/** Material Symbols web SVGs use a 960-unit box shifted up by 960; the older ones a plain 24-unit box. */
private fun symbol(name: String, box: Float, path: String): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = box, viewportHeight = box)
        .addGroup(translationY = if (box > 24f) box else 0f)
        .addPath(addPathNodes(path), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
